import React from 'react';
import { Link } from 'react-router-dom';
import { API_BASE_URL } from '../config/apiConfig';
import { PhotoIcon } from '@heroicons/react/24/outline';

const PhoneCard = ({ phone }) => {
  // 价格折扣百分比
  const discountPercent = phone.originalPrice
    ? Math.round(((phone.originalPrice - phone.price) / phone.originalPrice) * 100)
    : null;

  const imageUrl = phone.images && phone.images.length > 0 ? `${API_BASE_URL}${phone.images[0]}` : null;

  return (
    <Link to={`/phone/${phone._id}`} className="group block">
      <div className="w-full aspect-w-1 aspect-h-1 bg-gray-100 rounded-lg overflow-hidden">
        {imageUrl ? (
          <img
            src={imageUrl}
            alt={phone.title}
            className="w-full h-full object-center object-cover group-hover:opacity-75"
          />
        ) : (
          <div className="flex items-center justify-center h-full">
            <PhotoIcon className="h-8 w-8 text-gray-300" aria-hidden="true" />
          </div>
        )}
        {discountPercent && discountPercent > 0 && (
          <div className="absolute top-2 right-2 bg-red-500 text-white text-xs font-bold px-2 py-1 rounded">
            {discountPercent}% OFF
          </div>
        )}
        <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/60 to-transparent p-3">
          <span className="inline-block px-2 py-1 text-xs text-white bg-primary-600 rounded">
            {phone.condition}
          </span>
        </div>
      </div>
      <div className="p-4">
        <h3 className="text-sm font-medium text-gray-900 line-clamp-2">
          {phone.title}
        </h3>
        <div className="mt-2 flex justify-between items-center">
          <div>
            <p className="text-lg font-bold text-primary-600">¥{phone.price}</p>
            {phone.originalPrice && (
              <p className="text-xs text-gray-500 line-through">
                ¥{phone.originalPrice}
              </p>
            )}
          </div>
          <div className="text-xs text-gray-500">
            {phone.brand} · {phone.storage}
          </div>
        </div>
      </div>
    </Link>
  );
};

export default PhoneCard;
